"""Report matched saved discovery on/off generation, not calibrated performance."""
from collections import Counter
import json,html
from pathlib import Path

ROOT=Path('research/analyst_outlier_discovery_20261014')
def name(p):return p.get('name',p.get('player_name',p['player_id']))
def signature(l):return tuple(sorted(str(p['player_id']) for p in l))
def total(l,k):return sum(float(p[k]) for p in l)
def main():
    results={arm:json.loads((ROOT/(arm+'_result.json')).read_text()) for arm in ['off','on']};on=results['on'];engine=on['football_analyst'];discovery=engine['discovery'];plan=engine['scenario_allocation_plan'];packet=json.load(open('research/sunday_main_analyst_20261013/discovery_semantic_v1/v4_final/packet.json'));source={s['source_id']:s for s in packet['sources']}
    before=json.loads((ROOT/'off_request.json').read_text());after=json.loads((ROOT/'on_request.json').read_text())
    before['optimizer'].pop('optimizer_run_id');after['optimizer'].pop('optimizer_run_id');before['optimizer']['params'].pop('analyst_discovery_enabled');after['optimizer']['params'].pop('analyst_discovery_enabled');assert before==after
    for r in results.values():
        assert r['status']=='completed' and len(r['results'])==5 and r['entry_readiness']['entry_ready'] is False
